<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>${escape(title)} — Workboard</title>
<style>
* { box-sizing: border-box; }
body { margin: 0; background: #f4f6fa; color: #182539; font-family: system-ui, sans-serif; }
main { max-width: 760px; margin: 64px auto; padding: 32px; background: white; border: 1px solid #dce2eb; border-radius: 12px; }
h1 { margin-top: 0; } h2 { font-size: 1.2rem; margin-top: 32px; }
label { display: block; font-weight: 600; margin-bottom: 8px; }
input { padding: 10px; font: inherit; border: 1px solid #8795a9; border-radius: 6px; width: 100%; }
button { padding: 10px 16px; font: inherit; font-weight: 600; color: white; background: #245bc0; border: 0; border-radius: 6px; cursor: pointer; }
button:disabled { opacity: .5; cursor: not-allowed; }
button:hover { background: #194695; } :focus-visible { outline: 3px solid #a64d00; outline-offset: 3px; }
.create { display: flex; gap: 12px; align-items: end; } .field { flex: 1; }
.project { display: flex; gap: 16px; align-items: center; justify-content: space-between; padding: 16px 0; border-top: 1px solid #dce2eb; }
.project span { overflow-wrap: anywhere; min-width: 0; } .project form { flex-shrink: 0; }
select { padding: 10px; font: inherit; }
.task { display: flex; align-items: center; gap: 12px; padding: 16px 0; border-top: 1px solid #dce2eb; overflow-wrap: anywhere; }
.task { flex-wrap: wrap; }
.task input { width: auto; } .task form { margin: 0; }
.task .create { flex: 1; } .task .field input { width: 100%; }
[role=alert] { color: #a31919; font-weight: 600; }
@media (max-width: 540px) { main { margin: 16px; padding: 20px; } .create { flex-direction: column; align-items: stretch; } }
</style></head><body><main>${body}</main></body></html>`;
}

function projectList(error = '', name = '', filter = 'Active') {
  const projects = listProjects.all(filter === 'Archived' ? 1 : 0);
  return page('Projects', `<h1>Workboard</h1>
${error ? `<p role="alert">${escape(error)}</p>` : ''}
<form class="create" method="post" action="/projects">
<div class="field"><label for="project-name">Project name</label><input id="project-name" name="name" value="${escape(name)}"></div>
<button type="submit">Create project</button></form>
<h2>Projects</h2>
<form method="get" action="/">
<label for="project-filter">Project filter</label>
<select id="project-filter" name="filter" onchange="this.form.requestSubmit()">${['Active', 'Archived'].map(value => `<option${value === filter ? ' selected' : ''}>${value}</option>`).join('')}</select>
</form>
${projects.length ? projects.map(project => `<div class="project" data-testid="project-row"><span>${escape(project.name)}</span><span data-testid="project-summary">${project.completed}/${project.total} completed</span><form action="/projects/${project.id}" method="get"><button type="submit">Open project</button></form><form action="/projects/${project.id}/${project.archived ? 'restore' : 'archive'}" method="post"><button type="submit">${project.archived ? 'Restore' : 'Archive'} project</button></form></div>`).join('') : '<p>No projects yet.</p>'}`);
}

function taskFilter(value) {
  return ['Open', 'Completed'].includes(value) ? value : 'All';
}

function projectPage(project, filter = 'All', error = '') {
  const tasks = listTasks.all(project.id).filter(task => filter === 'All' || Boolean(task.completed) === (filter === 'Completed'));
  return page(project.name, `<h1>${escape(project.name)}</h1>
<form action="/" method="get"><button type="submit">Projects</button></form>
${project.archived ? '<p>Archived project</p>' : ''}
${error ? `<p role="alert">${escape(error)}</p>` : ''}
<form class="create" method="post" action="/projects/${project.id}/rename">
<input type="hidden" name="filter" value="${filter}">
<div class="field"><label for="new-project-name">New project name</label><input id="new-project-name" name="name"${project.archived ? ' disabled' : ''}></div>
<button type="submit"${project.archived ? ' disabled' : ''}>Rename project</button></form>
<h2>Tasks</h2>
<form class="create" method="post" action="/projects/${project.id}/tasks">
<input type="hidden" name="filter" value="${filter}">
<div class="field"><label for="task-title">Task title</label><input id="task-title" name="title"></div>
<button type="submit"${project.archived ? ' disabled' : ''}>Create task</button></form>
<form method="get" action="/projects/${project.id}">
<label for="task-filter">Task filter</label>
<select id="task-filter" name="filter" onchange="this.form.requestSubmit()">${['All', 'Open', 'Completed'].map(value => `<option${value === filter ? ' selected' : ''}>${value}</option>`).join('')}</select>
</form>
${tasks.map(task => `<div class="task" data-testid="task-row">
<form method="post" action="/projects/${project.id}/tasks/${task.id}/completion">
<input type="hidden" name="filter" value="${filter}">
<input type="checkbox" name="completed" value="1" aria-label="Complete ${escape(task.title)}"${task.completed ? ' checked' : ''}${project.archived ? ' disabled' : ''} onchange="this.form.requestSubmit()">
</form><span>${escape(task.title)}</span>
<form method="post" action="/projects/${project.id}/tasks/${task.id}/priority">
<input type="hidden" name="filter" value="${filter}">
<label for="task-priority-${task.id}">Task priority</label>
<select id="task-priority-${task.id}" name="priority"${project.archived ? ' disabled' : ''} onchange="this.form.requestSubmit()">${['Low', 'Normal', 'High'].map(value => `<option${value === task.priority ? ' selected' : ''}>${value}</option>`).join('')}</select>
</form>
<form class="create" method="post" action="/projects/${project.id}/tasks/${task.id}/rename">
<input type="hidden" name="filter" value="${filter}">
<div class="field"><label for="new-task-title-${task.id}">New task title</label><input id="new-task-title-${task.id}" name="title"${project.archived ? ' disabled' : ''}></div>
<button type="submit"${project.archived ? ' disabled' : ''}>Rename task</button>
</form></div>`).join('')}`);
}

async function formData(req) {
  const chunks = [];
  let size = 0;
  for await (const chunk of req) {
    size += chunk.length;
    if (size > 65536) {
      const error = new Error('Request too large');
      error.status = 413;
      throw error;
    }
    chunks.push(chunk);
  }
  return new URLSearchParams(Buffer.concat(chunks).toString());
}

function html(res, status, body) {
  res.writeHead(status, { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-store' });
  res.end(body);
}

const server = http.createServer(async (req, res) => {
  try {
    const url = new URL(req.url, 'http://localhost');
    if (req.method === 'GET' && url.pathname === '/health') {
      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ status: 'ok' }));
    } else if (req.method === 'GET' && url.pathname === '/') {
      html(res, 200, projectList('', '', url.searchParams.get('filter') === 'Archived' ? 'Archived' : 'Active'));
    } else if (req.method === 'POST' && url.pathname === '/projects') {
      const body = await formData(req);
      const name = (body.get('name') || '').trim();
      if (!name) {
        html(res, 400, projectList('Project name is required'));
        return;
      }
      createProject.run(name);
      res.writeHead(303, { Location: '/' });
      res.end();
    } else if (req.method === 'POST' && /^\/projects\/\d+\/(archive|restore)$/.test(url.pathname)) {
      const parts = url.pathname.split('/');
      const result = archiveProject.run(parts[3] === 'archive' ? 1 : 0, parts[2]);
      if (!result.changes) {
        html(res, 404, page('Not found', '<h1>Project not found</h1>'));
        return;
      }
      res.writeHead(303, { Location: parts[3] === 'archive' ? '/' : '/?filter=Archived' });
      res.end();
    } else if (req.method === 'GET' && /^\/projects\/\d+$/.test(url.pathname)) {
      const project = findProject.get(url.pathname.split('/')[2]);
      if (!project) {
        html(res, 404, page('Not found', '<h1>Project not found</h1><form action="/"><button>Projects</button></form>'));
        return;
      }
      html(res, 200, projectPage(project, taskFilter(url.searchParams.get('filter'))));
    } else if (req.method === 'POST' && /^\/projects\/\d+\/rename$/.test(url.pathname)) {
      const project = findProject.get(url.pathname.split('/')[2]);
      if (!project) {
        html(res, 404, page('Not found', '<h1>Project not found</h1>'));
        return;
      }
      const body = await formData(req);
      const filter = taskFilter(body.get('filter'));
      if (project.archived) {
        html(res, 403, projectPage(project, filter, 'Archived project cannot be changed'));
        return;
      }
      const name = (body.get('name') || '').trim();
      if (!name) {
        html(res, 400, projectPage(project, filter, 'Project name is required'));
        return;
      }
      renameProject.run(name, project.id);
      res.writeHead(303, { Location: `/projects/${project.id}?filter=${filter}` });
      res.end();
    } else if (req.method === 'POST' && /^\/projects\/\d+\/tasks(?:\/\d+\/(?:completion|rename|priority))?$/.test(url.pathname)) {
      const parts = url.pathname.split('/');
      const project = findProject.get(parts[2]);
      if (!project) {
        html(res, 404, page('Not found', '<h1>Project not found</h1>'));
        return;
      }
      const body = await formData(req);
      const filter = taskFilter(body.get('filter'));
      if (project.archived) {
        html(res, 403, projectPage(project, filter, 'Archived project cannot be changed'));
        return;
      }
      if (parts[4]) {
        let result;
        if (parts[5] === 'rename') {
          const title = (body.get('title') || '').trim();
          if (!title) {
            html(res, 400, projectPage(project, filter, 'Task title is required'));
            return;
          }
          result = renameTask.run(title, parts[4], project.id);
        } else if (parts[5] === 'priority') {
          const priority = body.get('priority');
          if (!['Low', 'Normal', 'High'].includes(priority)) {
            html(res, 400, projectPage(project, filter, 'Invalid task priority'));
            return;
          }
          result = updatePriority.run(priority, parts[4], project.id);
        } else {
          result = updateTask.run(body.get('completed') === '1' ? 1 : 0, parts[4], project.id);
        }
        if (!result.changes) {
          html(res, 404, page('Not found', '<h1>Task not found</h1>'));
          return;
        }
      } else {
        const title = (body.get('title') || '').trim();
        if (!title) {
          html(res, 400, projectPage(project, filter, 'Task title is required'));
          return;
        }
        createTask.run(project.id, title);
      }
      res.writeHead(303, { Location: `/projects/${project.id}?filter=${filter}` });
      res.end();
    } else {
      html(res, 404, page('Not found', '<h1>Page not found</h1>'));
    }
  } catch (error) {
    console.error(error);
    if (!res.headersSent) html(res, error.status || 500, page('Error', `<h1>${error.status === 413 ? 'Request too large' : 'Something went wrong'}</h1>`));
    else res.end();
  }
});

server.listen(Number(process.env.PORT || 8080), '0.0.0.0');
for (const signal of ['SIGINT', 'SIGTERM']) {
  process.on(signal, () => server.close(() => { db.close(); process.exit(0); }));
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { once } from 'node:events';
import net from 'node:net';
import { DatabaseSync } from 'node:sqlite';

test('projects validate, navigate, and persist across restarts', async () => {
  const directory = await mkdtemp(join(tmpdir(), 'workboard-test-'));
  // Exercise upgrade from the original projects schema as well as fresh task storage.
  const legacy = new DatabaseSync(join(directory, 'projects.sqlite'));
  legacy.exec('CREATE TABLE projects (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL)');
  legacy.close();
  const socket = net.createServer();
  socket.listen(0, '127.0.0.1');
  await once(socket, 'listening');
  const port = socket.address().port;
  await new Promise(resolve => socket.close(resolve));
  const base = `http://127.0.0.1:${port}`;
  let child;
  let errors = '';
  async function start() {
    child = spawn(process.execPath, ['server.js'], {
      env: { ...process.env, PORT: String(port), DB_PATH: join(directory, 'projects.sqlite') },
      stdio: ['ignore', 'ignore', 'pipe']
    });
    child.stderr.on('data', chunk => { errors += chunk; });
    for (let attempt = 0; attempt < 100; attempt++) {
      try { if ((await fetch(`${base}/health`)).ok) return; } catch {}
      await new Promise(resolve => setTimeout(resolve, 30));
    }
    throw new Error(`Server did not start: ${errors}`);
  }
  async function stop() {
    if (child && child.exitCode === null) {
      const exited = once(child, 'exit');
      child.kill('SIGTERM');
      await exited;
    }
  }
  async function create(name) {
    return fetch(`${base}/projects`, {
      method: 'POST', body: new URLSearchParams({ name }), redirect: 'manual'
    });
  }
  try {
    await start();
    assert.deepEqual(await (await fetch(`${base}/health`)).json(), { status: 'ok' });
    const initial = await (await fetch(base)).text();
    assert.match(initial, /<h1>Workboard<\/h1>/);
    assert.match(initial, /<label for="project-name">Project name<\/label>/);
    assert.match(initial, />Create project<\/button>/);
    for (const name of ['', '   ']) {
      const response = await create(name);
      assert.equal(response.status, 400);
      const body = await response.text();
      assert.match(body, /role="alert">Project name is required/);
      assert.doesNotMatch(body, /data-testid="project-row"/);
    }
    assert.equal((await create('  First project  ')).status, 303);
    assert.equal((await create('Second <project>')).status, 303);
    const list = await (await fetch(base)).text();
    assert.equal((list.match(/data-testid="project-row"/g) || []).length, 2);
    assert.ok(list.indexOf('First project') < list.indexOf('Second &lt;project&gt;'));
    assert.match(list, /<span>First project<\/span>/);
    const path = list.match(/action="(\/projects\/\d+)" method="get"/)[1];
    const detail = await (await fetch(base + path)).text();
    assert.match(detail, /<h1>First project<\/h1>/);
    assert.match(detail, /action="\/" method="get"><button type="submit">Projects/);
    await stop();
    await start();
    assert.equal(await (await fetch(base)).text(), list);
    assert.equal(await (await fetch(base + path)).text(), detail);
    assert.equal((await fetch(`${base}/projects/999999`)).status, 404);

    async function post(route, values) {
      return fetch(base + route, { method: 'POST', body: new URLSearchParams(values), redirect: 'manual' });
    }
    async function detailPage(filter = 'All') {
      return (await fetch(`${base}${path}?filter=${filter}`)).text();
    }
    for (const title of ['', '   ']) {
      const response = await post(`${path}/tasks`, { title });
      assert.equal(response.status, 400);
      const body = await response.text();
      assert.match(body, /role="alert">Task title is required/);
      assert.doesNotMatch(body, /data-testid="task-row"/);
    }
    assert.equal((await post(`${path}/tasks`, { title: '  First task  ' })).status, 303);
    assert.equal((await post(`${path}/tasks`, { title: 'Second <task>' })).status, 303);
    let tasks = await detailPage();
    assert.match(tasks, /<label for="task-title">Task title/);
    assert.match(tasks, /<label for="task-filter">Task filter/);
    assert.match(tasks, /<option selected>All<\/option><option>Open<\/option><option>Completed<\/option>/);
    assert.equal((tasks.match(/data-testid="task-row"/g) || []).length, 2);
    assert.ok(tasks.indexOf('<span>First task') < tasks.indexOf('<span>Second &lt;task&gt;'));
    assert.match(tasks, /aria-label="Complete First task" onchange/);
    const completion = tasks.match(/action="([^\"]+\/completion)"/)[1];
    assert.equal((await post(completion, { completed: '1' })).status, 303);
    tasks = await detailPage();
    assert.match(tasks, /aria-label="Complete First task" checked/);
    assert.doesNotMatch(await detailPage('Open'), /<span>First task/);
    assert.match(await detailPage('Open'), /<span>Second &lt;task&gt;/);
    assert.match(await detailPage('Completed'), /<span>First task/);
    assert.doesNotMatch(await detailPage('Completed'), /<span>Second &lt;task&gt;/);
    assert.doesNotMatch(await (await fetch(`${base}/projects/2`)).text(), /data-testid="task-row"/);
    assert.equal((await post(completion.replace('/projects/1/', '/projects/2/'), { completed: '0' })).status, 404);
    await stop();
    await start();
    assert.equal(await detailPage(), tasks);
    let summaryList = await (await fetch(base)).text();
    assert.match(summaryList, /<label for="project-filter">Project filter/);
    assert.match(summaryList, /<option selected>Active<\/option><option>Archived<\/option>/);
    assert.match(summaryList, /data-testid="project-summary">1\/2 completed/);
    assert.match(summaryList, /data-testid="project-summary">0\/0 completed/);
    assert.equal((await post(`${path}/archive`, {})).status, 303);
    assert.doesNotMatch(await (await fetch(base)).text(), /<span>First project/);
    const archivedList = await (await fetch(`${base}/?filter=Archived`)).text();
    assert.match(archivedList, /<span>First project/);
    assert.match(archivedList, /Restore project/);
    assert.match(archivedList, /data-testid="project-summary">1\/2 completed/);
    const archivedPage = await detailPage();
    assert.match(archivedPage, /<p>Archived project<\/p>/);
    assert.match(archivedPage, /disabled>Create task/);
    assert.equal((archivedPage.match(/type="checkbox"[^>]* disabled onchange/g) || []).length, 2);
    assert.match(await detailPage('Completed'), /<span>First task/);
    assert.doesNotMatch(await detailPage('Open'), /<span>First task/);
    assert.equal((await post(completion, {})).status, 403);
    assert.equal((await post(`${path}/tasks`, { title: 'Not allowed' })).status, 403);
    await stop();
    await start();
    assert.equal(await detailPage(), archivedPage);
    assert.equal(await (await fetch(`${base}/?filter=Archived`)).text(), archivedList);
    assert.equal((await post(`${path}/restore`, {})).status, 303);
    assert.doesNotMatch(await detailPage(), / disabled/);
    assert.match(await detailPage(), /aria-label="Complete First task" checked/);
    assert.match(await (await fetch(base)).text(), /data-testid="project-summary">1\/2 completed/);
    assert.doesNotMatch(await (await fetch(`${base}/?filter=Archived`)).text(), /data-testid="project-row"/);
    await stop();
    await start();
    assert.match(await (await fetch(base)).text(), /<span>First project/);
    assert.equal((await post(completion, {})).status, 303);
    assert.doesNotMatch(await detailPage(), /aria-label="Complete First task" checked/);
    assert.doesNotMatch(await detailPage('Completed'), /data-testid="task-row"/);
    assert.match(await (await fetch(base)).text(), /data-testid="project-summary">0\/2 completed/);
    await stop();
    await start();
    assert.doesNotMatch(await detailPage(), /aria-label="Complete First task" checked/);

    // Rename keeps the same URL, ordering, tasks, and completion summary.
    assert.equal((await post(completion, { completed: '1' })).status, 303);
    const beforeRename = await detailPage();
    assert.match(beforeRename, /<label for="new-project-name">New project name<\/label>/);
    assert.match(beforeRename, />Rename project<\/button>/);
    for (const name of ['', '   ']) {
      const response = await post(`${path}/rename`, { name });
      assert.equal(response.status, 400);
      const body = await response.text();
      assert.match(body, /role="alert">Project name is required/);
      assert.match(body, /<h1>First project<\/h1>/);
      assert.equal(await detailPage(), beforeRename);
    }
    assert.equal((await post('/projects/999999/rename', { name: 'Missing' })).status, 404);
    const renamed = await post(`${path}/rename`, { name: '  Renamed <project>  ', filter: 'Completed' });
    assert.equal(renamed.status, 303);
    assert.equal(renamed.headers.get('location'), `${path}?filter=Completed`);
    const renamedPage = await detailPage();
    assert.match(renamedPage, /<h1>Renamed &lt;project&gt;<\/h1>/);
    assert.match(renamedPage, /aria-label="Complete First task" checked/);
    assert.match(renamedPage, /<span>Second &lt;task&gt;<\/span>/);
    const renamedList = await (await fetch(base)).text();
    assert.ok(renamedList.indexOf('<span>Renamed &lt;project&gt;') < renamedList.indexOf('<span>Second &lt;project&gt;'));
    assert.match(renamedList, /data-testid="project-summary">1\/2 completed/);
    assert.match(renamedList, new RegExp(`action="${path}" method="get"`));
    await stop();
    await start();
    assert.equal(await detailPage(), renamedPage);
    assert.equal(await (await fetch(base)).text(), renamedList);
    await post(`${path}/archive`, {});
    const archivedRenamedPage = await detailPage();
    assert.match(archivedRenamedPage, /id="new-project-name" name="name" disabled/);
    assert.match(archivedRenamedPage, /disabled>Rename project/);
    assert.equal((await post(`${path}/rename`, { name: 'Forbidden' })).status, 403);
    assert.equal(await detailPage(), archivedRenamedPage);
    await post(`${path}/restore`, {});
    assert.doesNotMatch(await detailPage(), / disabled/);
    assert.equal((await post(`${path}/rename`, { name: 'Restored name' })).status, 303);
